// src/jobs/receipts.ts
var RECEIPT_SCHEMA = "eo-receipt/1";
var HASH_LIMIT_BYTES = 8 * 1024 * 1024;
function receiptRel(stage) {
  return "receipts/" + stage + ".json";
}
function receiptPath(fs, jobDir2, stage) {
  return fs.join(jobDir2, "receipts", stage + ".json");
}
async function describeOutputs(fs, jobDir2, relPaths) {
  const out = [];
  for (const rel4 of relPaths) {
    const abs = fs.join(jobDir2, ...rel4.split("/"));
    const st = await statFile(fs, abs);
    if (!st) throw new Error("The stage reported an output that does not exist: " + rel4);
    if (st.size <= HASH_LIMIT_BYTES) out.push({ path: rel4, bytes: st.size, sha256: await sha256Hex(await readBytes(fs, abs)) });
    else out.push({ path: rel4, bytes: st.size, mtimeMs: st.mtimeMs });
  }
  return out;
}
async function writeReceipt(fs, jobDir2, r5) {
  const receipt = { schema: RECEIPT_SCHEMA, ...r5, outputSha: r5.outputSha ?? await hashJson(r5.outputs) };
  await writeJsonAtomic(fs, receiptPath(fs, jobDir2, r5.stage), receipt);
  return receipt;
}
async function readReceipt(fs, jobDir2, stage) {
  const r5 = await readJsonIfExists(fs, receiptPath(fs, jobDir2, stage), null);
  return r5 && r5.schema === RECEIPT_SCHEMA ? r5 : null;
}
async function inputShaFrom(fs, jobDir2, upstream, extra = null) {
  const parts = {};
  for (const s of upstream) parts[s] = (await readReceipt(fs, jobDir2, s))?.outputSha ?? null;
  return hashJson({ upstream: parts, extra });
}
async function interruptedReceipt(fs, jobDir2, state2, stage, inputSha) {
  if (!state2 || state2.status !== "running" || state2.startedAt == null) return null;
  const r5 = await readReceipt(fs, jobDir2, stage);
  if (!r5 || r5.inputSha !== inputSha || r5.startedAt !== state2.startedAt || !Array.isArray(r5.outputs)) return null;
  let now;
  try {
    now = await describeOutputs(fs, jobDir2, r5.outputs.map((o) => o.path));
  } catch {
    return null;
  }
  return await hashJson(now) === r5.outputSha ? r5 : null;
}

