    lease = await acquireLease(fs, dir, { owner: o.owner ?? newOwnerId(), jobId: job.jobId, now: host2.now, ttlMs: o.leaseTtlMs, staleMs: o.leaseStaleMs, confirmDelayMs: o.leaseConfirmDelayMs });
